CREATE OR REPLACE FUNCTION public.new_tables_get_api_grants()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  obj record;
begin
  for obj in
    select object_type, object_identity
    from pg_event_trigger_ddl_commands()
